#include <stdio.h>

int main(void)
{
    int x, y, a;

    scanf("%d %d %d", &x, &y, &a);

    switch ((a / 90) % 4)
    {
        case 0:
            printf("%d %d\n", x, y);
            break;

        case 1:
            printf("%d %d\n", -y, x);
            break;

        case 2:
            printf("%d %d\n", -x, -y);
            break;

        case 3:
            printf("%d %d\n", y, -x);
            break;
    }

    return 0;
}
